#include "coupled_rk4_propagator.hpp"
#include "coupled_dop853_propagator.hpp"
#include <pybind11/eigen.h>
#include <pybind11/numpy.h>
#include <cmath>
#include <chrono>
#include <cstdio>
#include <limits>
#include <vector>
namespace py=pybind11;
namespace omni::propagation {
static py::tuple output(const std::vector<double>& times,const std::vector<Vector>& states){py::array_t<double> t(times.size()),y({static_cast<py::ssize_t>(states.size()),static_cast<py::ssize_t>(states[0].size())});auto ta=t.mutable_unchecked<1>();auto ya=y.mutable_unchecked<2>();for(std::size_t i=0;i<times.size();++i){ta(i)=times[i];for(Eigen::Index j=0;j<states[i].size();++j)ya(i,j)=states[i][j];}return py::make_tuple(t,y);}
py::tuple integrate_rk4(Vector y,double jd,double dt,double tf,const py::object& p,bool progress){if(!std::isfinite(tf)||tf<0)throw py::value_error("tf must be finite and nonnegative seconds");RuntimeScope runtime_scope(p);project(y,p);py::object bar=progress?py::module_::import("tqdm").attr("tqdm")(py::arg("total")=static_cast<std::size_t>(std::floor(tf/dt))+(tf-std::floor(tf/dt)*dt>1e-12*std::max(1.,tf)),py::arg("desc")="Running coupled RK4",py::arg("unit")="step"):py::none();std::vector<double> times{0.};std::vector<Vector> states{y};const auto full=static_cast<std::size_t>(std::floor(tf/dt));double remainder=tf-full*dt;if(remainder<=1e-12*std::max(1.,tf))remainder=0;for(std::size_t i=0;i<full+(remainder>0);++i){double elapsed=i*dt,h=i==full?remainder:dt;y=rk4_step(y,jd+elapsed/86400.,h,p);times.push_back(std::min((i+1)*dt,tf));states.push_back(y);if(progress)bar.attr("update")(1);}times.back()=tf;if(progress)bar.attr("close")();return output(times,states);}
py::tuple integrate_dop853(Vector y,double jd,double dt,double tf,const py::object& p,double rtol,Vector atol,double max_step,double min_step,bool progress){if(!std::isfinite(tf)||tf<0)throw py::value_error("tf must be finite and nonnegative seconds");RuntimeScope runtime_scope(p);project(y,p);py::object bar=progress?py::module_::import("tqdm").attr("tqdm")(py::arg("total")=tf,py::arg("desc")="Running coupled DOP853",py::arg("unit")="sim s",py::arg("bar_format")="{desc}: {percentage:3.0f}%|{bar}| {n_fmt}/{total_fmt} sim s [{elapsed}<{remaining}{postfix}]"):py::none();if(atol.size()==1)atol=Vector::Constant(y.size(),atol[0]);if(atol.size()!=y.size())throw py::value_error("atol length differs from state size");std::vector<double> times{0.};std::vector<Vector> states{y};if(tf==0)return output(times,states);const auto progress_start=std::chrono::steady_clock::now();auto show_rate=[&](){if(!progress)return;const double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-progress_start).count();char message[96];std::snprintf(message,sizeof(message),"%zu steps, %.0f step/s",states.size()-1,seconds>0?(states.size()-1)/seconds:0.);bar.attr("set_postfix_str")(message,py::arg("refresh")=false);};double t=0,h=std::min(dt,max_step);Vector f=derivative(y,jd,p);std::size_t trials=0;while(t<tf){if(++trials>10000000)throw py::value_error("DOP853 exceeded maximum trials");double remaining=tf-t,step=std::min({h,max_step,remaining});if(step<=0||t+step==t)throw py::value_error("DOP853 step is too small to advance simulation time");if(step<min_step&&remaining>min_step)throw py::value_error("DOP853 reached min_step before satisfying tolerances");auto [candidate,next_f,error]=dop853_attempt(y,f,jd+t/86400.,step,p,rtol,atol);if(!std::isfinite(error))throw py::value_error("DOP853 produced a nonfinite error estimate");if(error<=1){t+=step;y=candidate;f=next_f;times.push_back(t);states.push_back(y);if(progress){bar.attr("update")(step);if((states.size()-1)%100==0)show_rate();}double factor=error==0?10.:std::min(10.,std::max(.2,.9*std::pow(error,-.125)));h=std::min(max_step,step*factor);}else{h=step*std::max(.2,.9*std::pow(error,-.125));if(h<min_step)throw py::value_error("DOP853 reached min_step before satisfying tolerances");}}if(progress){show_rate();bar.attr("close")();}return output(times,states);}
}
